INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000231',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss economic history at B2","Use Wirtschaftsgeschichte vocabulary","Talk about German economic development"],"explanation":{"intro":"Economic history vocabulary covers the development of the German economy, key phases, and economic transformation at B2.","culturalNote":"German Wirtschaftsgeschichte: Zollverein (customs union 1834 — precursor to German unification), Gründerzeit (founding era 1871-1873 — rapid industrialisation after unification), Weltwirtschaftskrise (Great Depression 1929), Wirtschaftswunder (economic miracle 1948-1960s — postwar recovery), Soziale Marktwirtschaft (social market economy — Ludwig Erhard), Wiedervereinigungskrise (reunification crisis 1990s), Agenda 2010 (Schröder reforms 2003), Finanzmarktkrise (financial crisis 2008)."},"examples":[{"german":"Das Wirtschaftswunder der Nachkriegszeit beruht auf einem einzigartigen Zusammenspiel von Marshallplan, Währungsreform, Arbeitsethos und dem Konzept der sozialen Marktwirtschaft.","english":"The economic miracle of the postwar period rests on a unique interplay of the Marshall Plan, currency reform, work ethic, and the concept of the social market economy."},{"german":"Die Geschichte der deutschen Wirtschaft ist geprägt von abrupten Brüchen — von der Hyperinflation 1923 über die Weltwirtschaftskrise bis zur Teilung und Wiedervereinigung — die jeweils institutionelle Neuordnungen erforderten.","english":"The history of the German economy is characterised by abrupt ruptures — from the hyperinflation of 1923 through the Great Depression to division and reunification — each of which required institutional reorderings."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German economic history, the Wirtschaftswunder, and the social market economy at B2."}}',
'{"items":[{"word":"das Wirtschaftswunder","translation":"economic miracle","pronunciation":"dahs VIRT-shafts-voon-der","example":"Wirtschaftswunder der Nachkriegszeit."},{"word":"beruhen auf","translation":"to rest on/be based on","pronunciation":"beh-ROO-en owf","example":"Auf einem Zusammenspiel beruhen."},{"word":"das Zusammenspiel","translation":"interplay","pronunciation":"dahs tsoo-ZA-men-shpeel","example":"Einzigartiges Zusammenspiel."},{"word":"der Bruch","translation":"rupture/break","pronunciation":"dayr brookh","example":"Abrupter Bruch."},{"word":"geprägt von","translation":"characterised by","pronunciation":"geh-PRÄKT fon","example":"Von Brüchen geprägt."},{"word":"die Neuordnung","translation":"reordering/reorganisation","pronunciation":"dee NOY-ord-noong","example":"Institutionelle Neuordnung."}]}',
'{"title":"Beruhen auf — to rest on, to be based on","pattern":"etwas beruht auf + dative = something rests on, is based on (describes the foundation of something)","explanation":"Beruhen auf + dative = to rest on, to be based on (describing foundations). Das Wirtschaftswunder beruht auf einem Zusammenspiel = The economic miracle rests on an interplay. Intransitive — the subject passively rests on its foundation. Perfect: hat beruht. Compare: basieren auf (to be based on — more direct, often technical), gründen auf (to found on — more active, more concrete), zurückzuführen sein auf (to be traceable to — causal attribution), hängen von ab (to depend on — dependency rather than foundation).","examples":[{"sentence":"Der Erfolg des Projekts beruht auf sorgfältiger Planung und gutem Teamwork.","translation":"The project''s success rests on careful planning and good teamwork."},{"sentence":"Seine Argumentation beruht auf falschen Prämissen.","translation":"His argumentation is based on false premises."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Wirtschaftswunder'' means?","options":["economic miracle","economic boom","economic recovery","economic success"],"correctAnswer":"economic miracle"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The economic miracle of the postwar period rests on a unique interplay of the Marshall Plan, currency reform, work ethic, and the concept of the social market economy.","options":["Das Wirtschaftswunder der Nachkriegszeit beruht auf einem einzigartigen Zusammenspiel von Marshallplan, Währungsreform, Arbeitsethos und dem Konzept der sozialen Marktwirtschaft.","Das Wirtschaftswunder war das Ergebnis harter Arbeit und amerikanischer Hilfe.","Die soziale Marktwirtschaft war der Schlüssel zum Wirtschaftswunder.","Deutschland baute seine Wirtschaft nach dem Krieg sehr schnell wieder auf."],"correctAnswer":"Das Wirtschaftswunder der Nachkriegszeit beruht auf einem einzigartigen Zusammenspiel von Marshallplan, Währungsreform, Arbeitsethos und dem Konzept der sozialen Marktwirtschaft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Erfolg des Projekts beruht auf sorgfältiger Planung und gutem ___.","options":["Teamwork","Zusammenarbeit","Kooperation","Team"],"correctAnswer":"Teamwork"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His argumentation is based on false premises","wordBankItems":["Seine","Argumentation","beruht","auf","falschen","Prämissen","."],"correctAnswer":"Seine Argumentation beruht auf falschen Prämissen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Neuordnung'' means?","options":["reordering/reorganisation","new order","restructuring","reorganisation"],"correctAnswer":"reordering/reorganisation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000232',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss industrialisation at B2","Use Industrialisierung vocabulary","Talk about 19th century economic transformation"],"explanation":{"intro":"Industrialisation vocabulary covers the shift from agrarian to industrial economy, social consequences, and German industrialisation at B2.","culturalNote":"German Industrialisierung: later than UK but rapid (1840s-1900). Key: Ruhrgebiet (Ruhr — coal and steel heartland), Krupp (steel dynasty), Siemens (electrical engineering), railways (Eisenbahn — integrating the economy), Urbanisierung (urbanisation — Berlin, Hamburg boom), Proletariat (working class), Verelendung (immiseration — Marx). Social consequences: Arbeiterfrage (labour question), Sozialversicherung (social insurance — Bismarck 1883-1889, first welfare state). Kinderarbeit (child labour), 14-hour workdays."},"examples":[{"german":"Die Industrialisierung löste einen tiefgreifenden sozialen Wandel aus: Sie zerstörte traditionelle Handwerkstrukturen, schuf das Industrieproletariat und erzwang neue staatliche Antworten auf die soziale Frage.","english":"Industrialisation triggered a profound social transformation: it destroyed traditional craft structures, created the industrial proletariat, and compelled new state responses to the social question."},{"german":"Das Ruhrgebiet entwickelte sich innerhalb weniger Jahrzehnte vom dünn besiedelten Agrarland zum dichtesten Industrierevier Europas.","english":"The Ruhr area developed within a few decades from sparsely populated agricultural land into the densest industrial region in Europe."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss industrialisation, its social consequences, and German economic history at B2."}}',
'{"items":[{"word":"tiefgreifend","translation":"profound/far-reaching","pronunciation":"TEEF-gry-fend","example":"Tiefgreifender Wandel."},{"word":"auslösen","translation":"to trigger/set off","pronunciation":"OWS-lö-zen","example":"Einen Wandel auslösen."},{"word":"erzwingen","translation":"to compel/force","pronunciation":"er-TSVING-en","example":"Neue Antworten erzwingen."},{"word":"dünn besiedelt","translation":"sparsely populated","pronunciation":"dünn beh-ZEE-delt","example":"Dünn besiedeltes Land."},{"word":"das Industrierevier","translation":"industrial region","pronunciation":"dahs in-doos-TREE-reh-veer","example":"Dichtestes Industrierevier."},{"word":"dicht","translation":"dense/densely","pronunciation":"dikht","example":"Dicht besiedelt."}]}',
'{"title":"Auslösen — to trigger, set off (cause an effect to start)","pattern":"etwas löst etwas aus = something triggers something else (separable — löst...aus; the cause starts a chain reaction)","explanation":"Auslösen (separable) = to trigger, to set off (a process, reaction, or chain of events that has its own momentum once started). Die Industrialisierung löste einen Wandel aus = Industrialisation triggered a transformation. Löst aus (present), löste aus (past), hat ausgelöst (perfect). Compare: verursachen (to cause — direct causation, not necessarily chain-reaction), hervorrufen (to bring about — similar but less emphasis on chain), bewirken (to bring about — emphasises effect, less emphasis on trigger), einen Dominoeffekt auslösen (to trigger a domino effect — extension).","examples":[{"sentence":"Der Kommentar löste eine heftige Debatte aus.","translation":"The comment triggered a fierce debate."},{"sentence":"Die Nachricht löste Panik an den Börsen aus.","translation":"The news triggered panic on the stock markets."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Tiefgreifend'' means?","options":["profound/far-reaching","deep","fundamental","thoroughgoing"],"correctAnswer":"profound/far-reaching"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Industrialisation triggered a profound social transformation: it destroyed traditional craft structures, created the industrial proletariat, and compelled new state responses to the social question.","options":["Die Industrialisierung löste einen tiefgreifenden sozialen Wandel aus: Sie zerstörte traditionelle Handwerkstrukturen, schuf das Industrieproletariat und erzwang neue staatliche Antworten auf die soziale Frage.","Die Industrialisierung veränderte die Gesellschaft grundlegend.","Das Industrieproletariat entstand durch die Industrialisierung.","Die soziale Frage entstand als Folge der Industrialisierung."],"correctAnswer":"Die Industrialisierung löste einen tiefgreifenden sozialen Wandel aus: Sie zerstörte traditionelle Handwerkstrukturen, schuf das Industrieproletariat und erzwang neue staatliche Antworten auf die soziale Frage."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Kommentar löste eine heftige Debatte ___.","options":["aus","los","ab","an"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The news triggered panic on the stock markets","wordBankItems":["Die","Nachricht","löste","Panik","an","den","Börsen","aus","."],"correctAnswer":"Die Nachricht löste Panik an den Börsen aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erzwingen'' means?","options":["to compel/force","to demand","to impose","to require"],"correctAnswer":"to compel/force"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000233',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of globalisation at B2","Use Globalisierungsgeschichte vocabulary","Talk about trade, colonialism, and integration"],"explanation":{"intro":"History of globalisation vocabulary covers waves of globalisation, colonialism, and the modern globalised economy at B2.","culturalNote":"Globalisierungsgeschichte: historians identify three major waves: 1) Proto-globalisation — Silk Road, Indian Ocean trade; 2) Modern globalisation 1820-1914 — European empires, steam ships, telegraph, gold standard; 3) Contemporary globalisation 1945/1990- — Bretton Woods, WTO, internet. German role: trading nation (Exportweltmeister — world export champion), Hanseatic League (Hanse — medieval trading network), Hamburg as global port. Key tensions: Freihandel vs. Protektionismus (free trade vs. protectionism), winners and losers of globalisation."},"examples":[{"german":"Die Geschichte der Globalisierung ist keine lineare Erfolgsgeschichte, sondern von Phasen des Rückzugs und der Abschottung unterbrochen worden — am deutlichsten zwischen 1914 und 1945.","english":"The history of globalisation is not a linear success story, but has been interrupted by phases of retreat and closure — most clearly between 1914 and 1945."},{"german":"Deutschland profitiert als Exportnation überproportional von offenen Weltmärkten, trägt aber durch den daraus resultierenden Leistungsbilanzüberschuss zur globalen Ungleichgewicht bei.","english":"Germany benefits as an export nation disproportionately from open world markets, but contributes through the resulting current account surplus to global imbalances."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the history of globalisation, Germany''s export role, and trade policy at B2."}}',
'{"items":[{"word":"linear","translation":"linear","pronunciation":"li-neh-AHR","example":"Lineare Erfolgsgeschichte."},{"word":"die Abschottung","translation":"closure/sealing off","pronunciation":"dee AP-shot-oong","example":"Abschottung vom Weltmarkt."},{"word":"unterbrechen","translation":"to interrupt","pronunciation":"oon-ter-BREKH-en","example":"Von Phasen unterbrochen."},{"word":"überproportional","translation":"disproportionately","pronunciation":"ü-ber-pro-por-tsyo-NAHL","example":"Überproportional profitieren."},{"word":"das Ungleichgewicht","translation":"imbalance","pronunciation":"dahs OON-glykh-geh-vikht","example":"Globales Ungleichgewicht."},{"word":"der Leistungsbilanzüberschuss","translation":"current account surplus","pronunciation":"dayr LYS-toonks-bi-lants-ü-ber-shoos","example":"Leistungsbilanzüberschuss."}]}',
'{"title":"Von etwas unterbrochen werden — to be interrupted by something","pattern":"etwas wird von X unterbrochen = something is interrupted by X (passive — the interruption comes from outside, disturbs an ongoing process)","explanation":"Von etwas unterbrochen werden = to be interrupted by something (passive). Die Geschichte ist von Phasen unterbrochen worden = The history has been interrupted by phases (Perfect passive: ist...worden — with worden for passive). Active: etwas unterbricht etwas (something interrupts something — present). Perfect passive: ist unterbrochen worden (NOT: ist unterbrochen geworden — worden is the passive auxiliary, not geworden). Compare: stoppen (to stop — more abrupt), hemmen (to impede — slower, partial), aufhalten (to hold up/interrupt — often stronger).","examples":[{"sentence":"Die Konferenz wurde von einem Zwischenfall unterbrochen.","translation":"The conference was interrupted by an incident."},{"sentence":"Die Verhandlungen sind mehrfach von technischen Problemen unterbrochen worden.","translation":"The negotiations have been interrupted several times by technical problems."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abschottung'' means?","options":["closure/sealing off","isolation","withdrawal","protectionism"],"correctAnswer":"closure/sealing off"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The history of globalisation is not a linear success story, but has been interrupted by phases of retreat and closure — most clearly between 1914 and 1945.","options":["Die Geschichte der Globalisierung ist keine lineare Erfolgsgeschichte, sondern von Phasen des Rückzugs und der Abschottung unterbrochen worden — am deutlichsten zwischen 1914 und 1945.","Globalisierung war nicht immer ein Fortschritt.","Zwischen 1914 und 1945 verlief die Globalisierung rückwärts.","Die Globalisierungsgeschichte ist durch Weltkriege unterbrochen worden."],"correctAnswer":"Die Geschichte der Globalisierung ist keine lineare Erfolgsgeschichte, sondern von Phasen des Rückzugs und der Abschottung unterbrochen worden — am deutlichsten zwischen 1914 und 1945."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Konferenz wurde von einem Zwischenfall ___.","options":["unterbrochen","gestoppt","abgebrochen","unterbrochen"],"correctAnswer":"unterbrochen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The negotiations have been interrupted several times by technical problems","wordBankItems":["Die","Verhandlungen","sind","mehrfach","von","technischen","Problemen","unterbrochen","worden","."],"correctAnswer":"Die Verhandlungen sind mehrfach von technischen Problemen unterbrochen worden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überproportional'' means?","options":["disproportionately","excessively","disproportionate","out of proportion"],"correctAnswer":"disproportionately"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000234',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the Cold War at B2","Use Kalter Krieg vocabulary","Talk about Germany''s role in the Cold War"],"explanation":{"intro":"Cold War vocabulary covers the East-West conflict, Germany''s division, and the role of ideology at B2.","culturalNote":"Germany at the centre of the Cold War: divided 1945 into four occupation zones, then BRD (West Germany) vs. DDR (East Germany) 1949-1990. Key: Berliner Mauer (Berlin Wall — built 1961, fell 1989), NATO (West) vs. Warschauer Pakt (Warsaw Pact, East), Nuklearstrategie (nuclear strategy), MAD (Mutual Assured Destruction), Entspannungspolitik (détente — Willy Brandt''s Ostpolitik), Pershing II (US missiles in West Germany — Nachrüstungsdebatte 1983), Stasi (East German secret police — 600,000 informers). Ende des Kalten Krieges (end of Cold War — 1989 Wende, 1990 Wiedervereinigung)."},"examples":[{"german":"Deutschland war während des Kalten Krieges nicht nur geografisch geteilt, sondern diente als Frontlinie zweier ideologisch unvereinbarer Gesellschaftsmodelle.","english":"Germany was during the Cold War not only geographically divided, but served as the front line of two ideologically irreconcilable social models."},{"german":"Die Wiedervereinigung Deutschlands 1990 war nicht das geplante Ergebnis diplomatischer Weitsicht, sondern das unerwartete Produkt des kollabierenden DDR-Regimes und des Drucks der Straße.","english":"Germany''s reunification in 1990 was not the planned result of diplomatic foresight, but the unexpected product of the collapsing GDR regime and pressure from the street."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Cold War, Germany''s division, and the events of 1989-1990 at B2."}}',
'{"items":[{"word":"unvereinbar","translation":"irreconcilable/incompatible","pronunciation":"oon-fer-YN-bahr","example":"Ideologisch unvereinbare Modelle."},{"word":"die Frontlinie","translation":"front line","pronunciation":"dee FRONT-li-nee-eh","example":"Als Frontlinie dienen."},{"word":"die Weitsicht","translation":"foresight","pronunciation":"dee VYT-zikht","example":"Diplomatische Weitsicht."},{"word":"kollabieren","translation":"to collapse","pronunciation":"ko-la-BEER-en","example":"Kollabierendes Regime."},{"word":"der Druck der Straße","translation":"pressure from the street","pronunciation":"dayr drook dayr SHTRAH-seh","example":"Druck der Straße."},{"word":"geplant","translation":"planned/deliberate","pronunciation":"geh-PLAHNT","example":"Das geplante Ergebnis."}]}',
'{"title":"Als + infinitive construction vs. als + nominalized — dienen als (to serve as)","pattern":"als + noun/role = as (a role or function) — used with dienen (serve), gelten (be regarded), fungieren (function)","explanation":"Als + noun phrase = as (fulfilling a role or function). Deutschland diente als Frontlinie = Germany served as the front line. Key verbs with als: dienen als (to serve as), gelten als (to be regarded as — with nominative), fungieren als (to function as), wirken als (to act as), eingesetzt werden als (to be deployed as). The noun after als takes nominative (als Frontlinie, not als Frontlinien). Compare: wie (like/as in comparisons — different from role marker), in der Funktion (in the function of — more bureaucratic), in der Rolle (in the role of — more theatrical).","examples":[{"sentence":"Das Dokument dient als Beweis für seine Unschuld.","translation":"The document serves as proof of his innocence."},{"sentence":"Sie fungiert in dieser Firma als Bindeglied zwischen Technik und Management.","translation":"She functions in this firm as a link between technology and management."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unvereinbar'' means?","options":["irreconcilable/incompatible","incompatible","contradictory","opposite"],"correctAnswer":"irreconcilable/incompatible"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany was during the Cold War not only geographically divided, but served as the front line of two ideologically irreconcilable social models.","options":["Deutschland war während des Kalten Krieges nicht nur geografisch geteilt, sondern diente als Frontlinie zweier ideologisch unvereinbarer Gesellschaftsmodelle.","Im Kalten Krieg war Deutschland geteilt und war das Zentrum des Ost-West-Konflikts.","Deutschland war die wichtigste Frontlinie des Kalten Krieges.","Die Teilung Deutschlands spiegelte den ideologischen Konflikt zwischen Ost und West wider."],"correctAnswer":"Deutschland war während des Kalten Krieges nicht nur geografisch geteilt, sondern diente als Frontlinie zweier ideologisch unvereinbarer Gesellschaftsmodelle."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Dokument dient als Beweis für seine ___.","options":["Unschuld","Schuld","Entschuldigung","Reinheit"],"correctAnswer":"Unschuld"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She functions in this firm as a link between technology and management","wordBankItems":["Sie","fungiert","in","dieser","Firma","als","Bindeglied","zwischen","Technik","und","Management","."],"correctAnswer":"Sie fungiert in dieser Firma als Bindeglied zwischen Technik und Management ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Weitsicht'' means?","options":["foresight","vision","perspective","long-term view"],"correctAnswer":"foresight"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000235',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss decolonisation at B2","Use Dekolonisierung vocabulary","Talk about the end of European empires"],"explanation":{"intro":"Decolonisation vocabulary covers the end of European colonial empires, independence movements, and postcolonial legacy at B2.","culturalNote":"Dekolonisierung: 1945-1975 wave of independence movements. Germany''s colonial history: Germany had colonies 1884-1919 (Kamerun, Tansania — Deutsch-Ostafrika, Namibia — Deutsch-Südwestafrika, and others). Herero and Nama genocide (1904-1908 in Namibia — Germany recognised as genocide in 2021). Key terms: Selbstbestimmungsrecht der Völker (right of peoples to self-determination), Neokolonialismus (neocolonialism — economic dependency after formal independence), postkoloniale Kritik (postcolonial critique). Germany''s reckoning: Restitution of artefacts, public debate about colonial past."},"examples":[{"german":"Der Prozess der Dekolonisierung war selten friedlich: Die europäischen Mächte hielten vielfach an kolonialen Interessen fest, was zu blutigen Unabhängigkeitskriegen führte.","english":"The process of decolonisation was rarely peaceful: the European powers frequently clung to colonial interests, which led to bloody wars of independence."},{"german":"Deutschland hat seinen Kolonialismus und den damit einhergehenden Genozid an den Herero und Nama in Namibia erst Jahrzehnte nach anderen Ländern als historische Schuld anerkannt.","english":"Germany acknowledged its colonialism and the genocide of the Herero and Nama in Namibia that accompanied it as a historical debt only decades after other countries."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss decolonisation, Germany''s colonial history, and postcolonial debates at B2."}}',
'{"items":[{"word":"festhalten an","translation":"to cling to/hold on to","pronunciation":"FEST-hal-ten an","example":"An Interessen festhalten."},{"word":"einhergehend mit","translation":"accompanying/going along with","pronunciation":"YN-hayr-gay-end mit","example":"Damit einhergehend."},{"word":"der Genozid","translation":"genocide","pronunciation":"dayr geh-no-TSEED","example":"Genozid anerkennen."},{"word":"anerkennen","translation":"to acknowledge/recognise","pronunciation":"an-er-KEN-en","example":"Als Schuld anerkennen."},{"word":"die Unabhängigkeit","translation":"independence","pronunciation":"dee oon-ap-HEN-ikh-kyt","example":"Erkämpfte Unabhängigkeit."},{"word":"das Selbstbestimmungsrecht","translation":"right to self-determination","pronunciation":"dahs ZELP-st-beh-STIM-oonks-rekht","example":"Selbstbestimmungsrecht."}]}',
'{"title":"Festhalten an — to cling to, to hold on to (persist with)","pattern":"an etwas festhalten = to cling to something, to hold on to (to maintain a position/interest despite pressure to abandon it)","explanation":"An etwas festhalten = to cling to something, to stick to (despite pressure to let go). Die Mächte hielten an kolonialen Interessen fest = The powers clung to colonial interests. Intransitive (kein Akkusativobjekt, only dative after an). Perfect: hat festgehalten. Compare: beibehalten (to maintain/keep — more neutral, deliberate choice), aufrechterhalten (to maintain — more formal, often institutional), beharren auf (to insist on — more stubborn), sich weigern aufzugeben (to refuse to give up — more explicit refusal).","examples":[{"sentence":"Das Unternehmen hält trotz Verlusten an seiner bisherigen Strategie fest.","translation":"The company is clinging to its previous strategy despite losses."},{"sentence":"Er hält an seinen Grundsätzen fest, egal was andere sagen.","translation":"He holds on to his principles no matter what others say."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Genozid'' means?","options":["genocide","ethnic cleansing","massacre","atrocity"],"correctAnswer":"genocide"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The process of decolonisation was rarely peaceful: the European powers frequently clung to colonial interests, which led to bloody wars of independence.","options":["Der Prozess der Dekolonisierung war selten friedlich: Die europäischen Mächte hielten vielfach an kolonialen Interessen fest, was zu blutigen Unabhängigkeitskriegen führte.","Die Dekolonisierung verlief manchmal friedlich, manchmal gewaltsam.","Europäische Mächte gaben ihre Kolonien ungern auf.","Unabhängigkeitskriege entstanden, weil Kolonien nicht freiwillig entlassen wurden."],"correctAnswer":"Der Prozess der Dekolonisierung war selten friedlich: Die europäischen Mächte hielten vielfach an kolonialen Interessen fest, was zu blutigen Unabhängigkeitskriegen führte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Unternehmen hält trotz Verlusten an seiner bisherigen Strategie ___.","options":["fest","an","bei","durch"],"correctAnswer":"fest"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He holds on to his principles no matter what others say","wordBankItems":["Er","hält","an","seinen","Grundsätzen","fest",",","egal","was","andere","sagen","."],"correctAnswer":"Er hält an seinen Grundsätzen fest , egal was andere sagen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anerkennen'' means?","options":["to acknowledge/recognise","to accept","to admit","to concede"],"correctAnswer":"to acknowledge/recognise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000236',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of human rights at B2","Use Menschenrechtsgeschichte vocabulary","Talk about the development of rights discourse"],"explanation":{"intro":"History of human rights vocabulary covers the development from Magna Carta to the UDHR and modern rights discourse at B2.","culturalNote":"Geschichte der Menschenrechte: Key milestones: Magna Carta 1215 (England), Habeas Corpus 1679, Glorious Revolution 1688 (England), American Declaration of Independence 1776, Déclaration des droits de l''homme 1789 (France), Abschaffung der Sklaverei (abolition of slavery — British 1833, US 1865), Genfer Konventionen (Geneva Conventions — 1864, 1949), Allgemeine Erklärung der Menschenrechte (UDHR 1948), EMRK 1950. German contribution: Grundgesetz 1949 (strong rights focus after Nazi atrocities — reaction to abuse of law)."},"examples":[{"german":"Die Allgemeine Erklärung der Menschenrechte von 1948 stellt einen zivilisatorischen Meilenstein dar, der aus den Erfahrungen zweier Weltkriege und des nationalsozialistischen Terrors hervorgegangen ist.","english":"The Universal Declaration of Human Rights of 1948 represents a civilisational milestone, which emerged from the experiences of two world wars and National Socialist terror."},{"german":"Menschenrechte werden nicht als staatliche Zugeständnisse betrachtet, sondern als vorstaatliche, unveräußerliche Rechte, die dem Einzelnen qua Menschenwürde zukommen.","english":"Human rights are not regarded as state concessions, but as pre-state, inalienable rights that accrue to the individual by virtue of human dignity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the history of human rights, the UDHR, and the philosophical basis of rights at B2."}}',
'{"items":[{"word":"hervorgehen aus","translation":"to emerge from","pronunciation":"her-FOR-gay-en ows","example":"Aus Erfahrungen hervorgehen."},{"word":"das Zugeständnis","translation":"concession","pronunciation":"dahs tsoo-geh-SHTENT-nis","example":"Staatliches Zugeständnis."},{"word":"vorstaatlich","translation":"pre-state","pronunciation":"FOR-shtaht-likh","example":"Vorstaatliche Rechte."},{"word":"unveräußerlich","translation":"inalienable","pronunciation":"oon-fer-OY-ser-likh","example":"Unveräußerliche Rechte."},{"word":"qua","translation":"by virtue of","pronunciation":"kvah","example":"Qua Menschenwürde."},{"word":"zukommen","translation":"to accrue to","pronunciation":"TSOO-ko-men","example":"Jemandem zukommen."}]}',
'{"title":"Hervorgehen aus — to emerge from (something gave rise to this)","pattern":"etwas geht aus etwas hervor = something emerges from something else (separable — geht...hervor; the result was produced by a process/source)","explanation":"Aus etwas hervorgehen = to emerge from, to come out of (separable: geht hervor, ging hervor, ist hervorgegangen). The UDHR ist aus den Erfahrungen der Weltkriege hervorgegangen = The UDHR emerged from the experiences of the world wars. Emphasises that something arose as a product of a process or source. Compare: entstehen aus (to arise from — more neutral process), resultieren aus (to result from — more causal), sich entwickeln aus (to develop from — evolutionary), sich ergeben aus (to follow from — logical consequence).","examples":[{"sentence":"Neue Ideen gehen oft aus dem Austausch unterschiedlicher Perspektiven hervor.","translation":"New ideas often emerge from the exchange of different perspectives."},{"sentence":"Das Werk ist aus jahrelanger Forschungsarbeit hervorgegangen.","translation":"The work emerged from years of research work."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unveräußerlich'' means?","options":["inalienable","immovable","inviolable","inherent"],"correctAnswer":"inalienable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Universal Declaration of Human Rights of 1948 represents a civilisational milestone, which emerged from the experiences of two world wars and National Socialist terror.","options":["Die Allgemeine Erklärung der Menschenrechte von 1948 stellt einen zivilisatorischen Meilenstein dar, der aus den Erfahrungen zweier Weltkriege und des nationalsozialistischen Terrors hervorgegangen ist.","Die Menschenrechtserklärung von 1948 ist die Grundlage moderner Menschenrechte.","Nach dem Zweiten Weltkrieg wurden universelle Menschenrechte kodifiziert.","Die AEMR war eine Reaktion auf die Gräuel der Weltkriege."],"correctAnswer":"Die Allgemeine Erklärung der Menschenrechte von 1948 stellt einen zivilisatorischen Meilenstein dar, der aus den Erfahrungen zweier Weltkriege und des nationalsozialistischen Terrors hervorgegangen ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Neue Ideen gehen oft aus dem Austausch unterschiedlicher Perspektiven ___.","options":["hervor","auf","heraus","raus"],"correctAnswer":"hervor"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The work emerged from years of research work","wordBankItems":["Das","Werk","ist","aus","jahrelanger","Forschungsarbeit","hervorgegangen","."],"correctAnswer":"Das Werk ist aus jahrelanger Forschungsarbeit hervorgegangen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Zugeständnis'' means?","options":["concession","admission","compromise","acknowledgement"],"correctAnswer":"concession"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000237',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of democracy at B2","Use Demokratiegeschichte vocabulary","Talk about Germany''s democratic development"],"explanation":{"intro":"History of democracy vocabulary covers democratic theory, historical development, and Germany''s turbulent democratic path at B2.","culturalNote":"Deutschlands Demokratiegeschichte: turbulent. Paulskirchenparlament 1848 (first failed democratic parliament — liberals defeated by conservatives), Kaiserreich 1871 (semi-authoritarian), Weimarer Republik 1919-1933 (first German democracy — failed, ended in NS), Drittes Reich 1933-1945, Grundgesetz 1949 (Federal Republic — designed to prevent Nazi-style takeover: no plebiscites, 5%-Hürde, konstruktives Misstrauensvotum). DDR called itself demokratisch (''Deutsche Demokratische Republik'') but was authoritarian. Wiedervereinigung 1990. Grundgesetz als Erfolgsgeschichte (GG success story)."},"examples":[{"german":"Die Weimarer Republik scheiterte nicht zwangsläufig an einem strukturellen Defekt, sondern an einer Konstellation von Wirtschaftskrise, politischer Radikalisierung und dem Versagen tragender Eliten.","english":"The Weimar Republic did not fail inevitably due to a structural defect, but through a constellation of economic crisis, political radicalisation, and the failure of load-bearing elites."},{"german":"Das Grundgesetz hat aus den Fehlern Weimars gelernt und schützt die Demokratie durch strukturelle Sicherungen wie die Ewigkeitsklausel und den Parteiverbotsmechanismus.","english":"The Basic Law has learnt from Weimar''s mistakes and protects democracy through structural safeguards like the eternity clause and the party ban mechanism."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s democratic history, the Weimar Republic, and the Basic Law at B2."}}',
'{"items":[{"word":"zwangsläufig","translation":"inevitably/necessarily","pronunciation":"TSVANGKS-löy-fikh","example":"Nicht zwangsläufig scheitern."},{"word":"die Konstellation","translation":"constellation/combination","pronunciation":"dee kon-shtel-ah-TSYOHN","example":"Konstellation von Faktoren."},{"word":"tragend","translation":"load-bearing/key","pronunciation":"TRAH-gend","example":"Tragende Eliten."},{"word":"die Ewigkeitsklausel","translation":"eternity clause","pronunciation":"dee AY-vikh-kyts-klow-zel","example":"Ewigkeitsklausel des Grundgesetzes."},{"word":"der Parteiverbotsmechanismus","translation":"party ban mechanism","pronunciation":"dayr par-TY-fer-bohts-meh-khan-is-moos","example":"Parteiverbotsmechanismus."},{"word":"die strukturelle Sicherung","translation":"structural safeguard","pronunciation":"dee shtroock-too-REL-eh ZI-khe-roong","example":"Strukturelle Sicherungen."}]}',
'{"title":"Nicht zwangsläufig — not inevitably, not necessarily (important qualifier for historical causation)","pattern":"nicht zwangsläufig = not inevitably/necessarily — used to challenge deterministic readings of history or events","explanation":"Zwangsläufig = inevitably, necessarily (from Zwang = compulsion + läufig = as it runs). Nicht zwangsläufig = not inevitably (rejecting a deterministic claim). The Weimar Republic scheiterte nicht zwangsläufig = did not fail inevitably (i.e. other outcomes were possible). Used frequently in historical analysis to argue against teleological or determinist readings. Compare: nicht unbedingt (not necessarily — more everyday), nicht notwendigerweise (not necessarily — more formal/philosophical), es hätte anders kommen können (it could have turned out differently — more hypothetical).","examples":[{"sentence":"Der Misserfolg war nicht zwangsläufig vorprogrammiert.","translation":"The failure was not inevitably predetermined."},{"sentence":"Veränderung geht nicht zwangsläufig mit Verbesserung einher.","translation":"Change does not inevitably go hand in hand with improvement."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zwangsläufig'' means?","options":["inevitably/necessarily","automatically","unavoidably","deterministically"],"correctAnswer":"inevitably/necessarily"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Weimar Republic did not fail inevitably due to a structural defect, but through a constellation of economic crisis, political radicalisation, and the failure of load-bearing elites.","options":["Die Weimarer Republik scheiterte nicht zwangsläufig an einem strukturellen Defekt, sondern an einer Konstellation von Wirtschaftskrise, politischer Radikalisierung und dem Versagen tragender Eliten.","Die Weimarer Republik scheiterte an wirtschaftlichen und politischen Problemen.","Verschiedene Faktoren führten zum Ende der Weimarer Republik.","Die Weimarer Republik war von Anfang an zum Scheitern verurteilt."],"correctAnswer":"Die Weimarer Republik scheiterte nicht zwangsläufig an einem strukturellen Defekt, sondern an einer Konstellation von Wirtschaftskrise, politischer Radikalisierung und dem Versagen tragender Eliten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Misserfolg war nicht zwangsläufig ___.","options":["vorprogrammiert","geplant","vorhersehbar","vorausbestimmt"],"correctAnswer":"vorprogrammiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Change does not inevitably go hand in hand with improvement","wordBankItems":["Veränderung","geht","nicht","zwangsläufig","mit","Verbesserung","einher","."],"correctAnswer":"Veränderung geht nicht zwangsläufig mit Verbesserung einher ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Tragend'' means?","options":["load-bearing/key","supporting","fundamental","crucial"],"correctAnswer":"load-bearing/key"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000238',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the history of the EU at B2","Use EU-Geschichte vocabulary","Talk about European integration milestones"],"explanation":{"intro":"EU history vocabulary covers the founding, expansion, and challenges of European integration at B2.","culturalNote":"EU history: EGKS (Europäische Gemeinschaft für Kohle und Stahl — ECSC 1951), EWG (Europäische Wirtschaftsgemeinschaft — EEC 1957, Römische Verträge), Einheitliche Europäische Akte 1986 (single market), Maastricht 1992 (Maastrichter Vertrag — monetary union, EU name, citizenship), Euro 2002, EU-Osterweiterung 2004 (10 new members — largest ever), Verfassungskrise 2005 (rejected referendums), Lissaboner Vertrag 2007, Finanzkrise 2008-2012 (Eurokrise), Brexit 2016/2020, COVID-Hilfspaket 2020 (Next Generation EU — eurobonds finally). Key debates: Supranationalität vs. Intergouvernementalismus."},"examples":[{"german":"Die europäische Integration folgte nicht einem vorgedachten Masterplan, sondern dem Prinzip der schrittweisen Vertiefung durch Krisen, die immer neue Integrationsschritte erforderten.","english":"European integration did not follow a pre-designed master plan, but the principle of gradual deepening through crises that always demanded new integration steps."},{"german":"Das europäische Integrationsprojekt ist ein historisches Novum: Erstmals haben souveräne Staaten freiwillig Kernkompetenzen auf eine übernationale Institution übertragen.","english":"The European integration project is a historical novelty: for the first time, sovereign states have voluntarily transferred core competencies to a supranational institution."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss EU history, European integration milestones, and key challenges at B2."}}',
'{"items":[{"word":"vorgedacht","translation":"pre-designed/pre-planned","pronunciation":"FOR-geh-dakht","example":"Vorgedachter Masterplan."},{"word":"schrittweise","translation":"gradual/step-by-step","pronunciation":"SHRIT-vy-zeh","example":"Schrittweise Vertiefung."},{"word":"die Vertiefung","translation":"deepening","pronunciation":"dee fer-TEE-foong","example":"Integration vertiefen."},{"word":"das Novum","translation":"novelty","pronunciation":"dahs NO-voom","example":"Historisches Novum."},{"word":"erstmals","translation":"for the first time","pronunciation":"ERST-mahls","example":"Erstmals geschehen."},{"word":"übernatonal","translation":"supranational","pronunciation":"ü-ber-nah-tsyo-NAHL","example":"Übernationale Institution."}]}',
'{"title":"Einem Prinzip folgen vs. einem Masterplan folgen — following a principle vs. a plan","pattern":"etwas folgt (nicht) einem X, sondern dem Prinzip Y = it does not follow X but rather operates on the principle of Y","explanation":"Etwas folgt einem Prinzip/Muster/Masterplan = something follows a principle/pattern/masterplan. Dative after folgen (jemandem/etwas folgen). Not einem vorgedachten Masterplan, sondern dem Prinzip = not a pre-designed masterplan, but the principle (contrast with sondern). Folgen + Dative can be concrete (follow a person) or abstract (follow a logic, principle, pattern). Compare: sich richten nach (to be guided by — more rules/norms), sich orientieren an (to orientate oneself by — more deliberate choice), entsprechen (to correspond to — more exact matching).","examples":[{"sentence":"Seine Entscheidungen folgen keiner klaren Logik.","translation":"His decisions follow no clear logic."},{"sentence":"Die Politik folgte dem Grundsatz der Verhältnismäßigkeit.","translation":"The policy followed the principle of proportionality."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Novum'' means?","options":["novelty","innovation","first","new development"],"correctAnswer":"novelty"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"European integration did not follow a pre-designed master plan, but the principle of gradual deepening through crises that always demanded new integration steps.","options":["Die europäische Integration folgte nicht einem vorgedachten Masterplan, sondern dem Prinzip der schrittweisen Vertiefung durch Krisen, die immer neue Integrationsschritte erforderten.","Die EU entstand durch eine Reihe von Verträgen und Erweiterungen.","Europäische Integration ist ein schrittweiser Prozess, der durch Krisen vorangetrieben wird.","Kein Masterplan steckt hinter der europäischen Integration."],"correctAnswer":"Die europäische Integration folgte nicht einem vorgedachten Masterplan, sondern dem Prinzip der schrittweisen Vertiefung durch Krisen, die immer neue Integrationsschritte erforderten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Politik folgte dem Grundsatz der ___.","options":["Verhältnismäßigkeit","Rationalität","Vernunft","Gleichheit"],"correctAnswer":"Verhältnismäßigkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His decisions follow no clear logic","wordBankItems":["Seine","Entscheidungen","folgen","keiner","klaren","Logik","."],"correctAnswer":"Seine Entscheidungen folgen keiner klaren Logik ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schrittweise'' means?","options":["gradual/step-by-step","step by step","incrementally","gradually"],"correctAnswer":"gradual/step-by-step"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000239',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss contemporary history at B2","Use Zeitgeschichte vocabulary","Talk about historical memory and historiography"],"explanation":{"intro":"Contemporary history vocabulary covers Zeitgeschichte as a discipline, methodological debates, and the politics of historical memory at B2.","culturalNote":"Zeitgeschichte (contemporary history): Germany has a particularly rich tradition of engaged contemporary history, tied to NS/DDR processing. Key institutions: Institut für Zeitgeschichte (IfZ Munich — founded 1949, focused on NS), Zentrum für Zeithistorische Forschung (ZZF Potsdam — DDR focus). Historikerstreit (historians'' debate 1986-1987 — Habermas vs. Nolte on uniqueness of Holocaust). Key concept: erlebte Geschichte (history lived by the generation studied), Augenzeugen (eyewitnesses), Oral History, Aktenüberlieferung (archival sources). Zeitgeschichte ends 1/3 living generation rule."},"examples":[{"german":"Der Historikerstreit von 1986 verdeutlichte, dass historische Interpretation nie rein akademisch ist, sondern stets politische und moralische Dimensionen besitzt.","english":"The Historians'' Dispute of 1986 illustrated that historical interpretation is never purely academic, but always possesses political and moral dimensions."},{"german":"Zeitgeschichte steht vor der methodischen Herausforderung, noch lebende Zeitzeugen als Quellen zu nutzen, ohne dabei die kritische Distanz zu verlieren, die historiografisches Arbeiten erfordert.","english":"Contemporary history faces the methodological challenge of using still-living contemporary witnesses as sources without losing the critical distance that historiographic work requires."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss contemporary history, the Historians'' Dispute, and methodological debates at B2."}}',
'{"items":[{"word":"verdeutlichen","translation":"to illustrate/make clear","pronunciation":"fer-DOYT-li-khen","example":"Etwas verdeutlichen."},{"word":"der Zeitzeuge","translation":"contemporary witness","pronunciation":"dayr TSYT-tsoy-geh","example":"Noch lebende Zeitzeugen."},{"word":"die Herausforderung","translation":"challenge","pronunciation":"dee her-OWS-for-der-oong","example":"Methodische Herausforderung."},{"word":"historiografisch","translation":"historiographic","pronunciation":"his-to-rio-gra-FISH","example":"Historiografisches Arbeiten."},{"word":"die kritische Distanz","translation":"critical distance","pronunciation":"dee KRI-tish-eh dis-TANTS","example":"Kritische Distanz wahren."},{"word":"rein","translation":"purely/solely","pronunciation":"ryn","example":"Rein akademisch."}]}',
'{"title":"Vor einer Herausforderung stehen — to face a challenge","pattern":"etwas/jemand steht vor einer Herausforderung = something/someone faces a challenge (vor + dative = facing, confronted by)","explanation":"Vor einer Herausforderung stehen = to face a challenge. Vor + dative signals standing in front of something (often an obstacle, decision, or challenge). Zeitgeschichte steht vor der Herausforderung... = Contemporary history faces the challenge... Common frames: vor einer Entscheidung stehen (to face a decision), vor einem Problem stehen (to face a problem), vor großen Aufgaben stehen (to face major tasks), vor einer Wahl stehen (to face a choice). Compare: sich einer Herausforderung stellen (to take on a challenge — more active, responsive), einer Herausforderung begegnen (to meet a challenge — more engaged), sich konfrontiert sehen mit (to find oneself confronted with — passive).","examples":[{"sentence":"Die Gesellschaft steht vor der Herausforderung des demografischen Wandels.","translation":"Society faces the challenge of demographic change."},{"sentence":"Wir stehen vor einer fundamentalen Entscheidung.","translation":"We face a fundamental decision."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdeutlichen'' means?","options":["to illustrate/make clear","to clarify","to explain","to demonstrate"],"correctAnswer":"to illustrate/make clear"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Historians'' Dispute of 1986 illustrated that historical interpretation is never purely academic, but always possesses political and moral dimensions.","options":["Der Historikerstreit von 1986 verdeutlichte, dass historische Interpretation nie rein akademisch ist, sondern stets politische und moralische Dimensionen besitzt.","Geschichte ist immer politisch und kann nicht neutral interpretiert werden.","Der Historikerstreit zeigte, dass Geschichte politisch umkämpft ist.","Historische Interpretation hat immer eine moralische Dimension."],"correctAnswer":"Der Historikerstreit von 1986 verdeutlichte, dass historische Interpretation nie rein akademisch ist, sondern stets politische und moralische Dimensionen besitzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Gesellschaft steht vor der Herausforderung des demografischen ___.","options":["Wandels","Wandel","Veränderung","Übergangs"],"correctAnswer":"Wandels"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We face a fundamental decision","wordBankItems":["Wir","stehen","vor","einer","fundamentalen","Entscheidung","."],"correctAnswer":"Wir stehen vor einer fundamentalen Entscheidung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Rein'' means?","options":["purely/solely","purely","only","merely"],"correctAnswer":"purely/solely"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000023a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Erinnerungskultur at B2","Use memory culture vocabulary","Talk about Germany''s reckoning with the past"],"explanation":{"intro":"Erinnerungskultur vocabulary covers Germany''s culture of remembrance, especially regarding the Nazi past, at B2.","culturalNote":"Erinnerungskultur (culture of remembrance): Germany has developed a distinctive and internationally noted Erinnerungskultur around the Nazi past. Key elements: Holocaustmahnmal (Memorial to the Murdered Jews of Europe — Berlin 2005), Stolpersteine (stumbling stones — individual memorial plaques, Gunter Demnig), Gedenkstätten (memorial sites — Auschwitz, Dachau, Buchenwald), Schuldbekenntnis (admission of guilt — Willy Brandt Kniefall 1970 Warsaw), Vergangenheitsbewältigung (working through the past), Schlussstrichforderungen (calls to draw a line under the past — right-wing)."},"examples":[{"german":"Deutschlands Erinnerungskultur ist international einzigartig: Kein anderes Land hat eine so institutionalisierte und gesellschaftlich verankerte Auseinandersetzung mit seinen schlimmsten historischen Verbrechen entwickelt.","english":"Germany''s culture of remembrance is internationally unique: no other country has developed such an institutionalised and societally anchored engagement with its worst historical crimes."},{"german":"Erinnerungskultur ist kein statisches Archiv, sondern ein dynamischer gesellschaftlicher Aushandlungsprozess, der sich mit jedem Generationenwechsel transformiert.","english":"Culture of remembrance is not a static archive, but a dynamic social negotiation process that transforms with every generational change."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s culture of remembrance, Vergangenheitsbewältigung, and historical accountability at B2."}}',
'{"items":[{"word":"verankert","translation":"anchored/embedded","pronunciation":"fer-ANG-kert","example":"Gesellschaftlich verankert."},{"word":"die Auseinandersetzung","translation":"engagement/confrontation","pronunciation":"dee ows-yn-an-der-ZET-soong","example":"Auseinandersetzung mit der Vergangenheit."},{"word":"das Schuldbekenntnis","translation":"admission of guilt","pronunciation":"dahs SHOOLT-beh-kent-nis","example":"Öffentliches Schuldbekenntnis."},{"word":"der Aushandlungsprozess","translation":"negotiation process","pronunciation":"dayr OWS-hand-looings-pro-tses","example":"Gesellschaftlicher Aushandlungsprozess."},{"word":"statisch","translation":"static","pronunciation":"SHTAH-tish","example":"Kein statisches Archiv."},{"word":"institutionalisiert","translation":"institutionalised","pronunciation":"in-sti-too-tsyo-nah-li-ZEERT","example":"Institutionalisierte Erinnerung."}]}',
'{"title":"Etwas ist verankert in — something is anchored in/embedded in (firmly established)","pattern":"etwas ist in etwas verankert = something is anchored in something (the thing is firmly embedded in, cannot easily be separated from its context)","explanation":"In etwas verankert sein = to be anchored in, to be deeply embedded in. Gesellschaftlich verankert = anchored in society (not just a surface phenomenon — deeply embedded). Der Schutz ist im Grundgesetz verankert = The protection is anchored in the Basic Law (legally entrenched). The metaphor of Anker (anchor) emphasises stability and firm embeddedness. Compare: verankert in (anchored in — most common), festgeschrieben in (written into — more legal, fixed in text), eingebettet in (embedded in — more neutral, context), verwurzelt in (rooted in — more organic, traditional).","examples":[{"sentence":"Das Recht auf freie Meinungsäußerung ist im Grundgesetz verankert.","translation":"The right to freedom of expression is anchored in the Basic Law."},{"sentence":"Diese Werte sind tief in der Gesellschaft verankert.","translation":"These values are deeply anchored in society."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Auseinandersetzung'' means?","options":["engagement/confrontation","debate","dispute","discussion"],"correctAnswer":"engagement/confrontation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s culture of remembrance is internationally unique: no other country has developed such an institutionalised and societally anchored engagement with its worst historical crimes.","options":["Deutschlands Erinnerungskultur ist international einzigartig: Kein anderes Land hat eine so institutionalisierte und gesellschaftlich verankerte Auseinandersetzung mit seinen schlimmsten historischen Verbrechen entwickelt.","Deutschland gedenkt seiner NS-Verbrechen wie kein anderes Land.","Die deutsche Erinnerungskultur ist ein Vorbild für andere Länder.","Kein anderes Land hat so viele Gedenkstätten für historische Verbrechen."],"correctAnswer":"Deutschlands Erinnerungskultur ist international einzigartig: Kein anderes Land hat eine so institutionalisierte und gesellschaftlich verankerte Auseinandersetzung mit seinen schlimmsten historischen Verbrechen entwickelt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Recht auf freie Meinungsäußerung ist im Grundgesetz ___.","options":["verankert","geschützt","festgeschrieben","garantiert"],"correctAnswer":"verankert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: These values are deeply anchored in society","wordBankItems":["Diese","Werte","sind","tief","in","der","Gesellschaft","verankert","."],"correctAnswer":"Diese Werte sind tief in der Gesellschaft verankert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Statisch'' means?","options":["static","fixed","unchanging","motionless"],"correctAnswer":"static"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

